void SQLServerNewDB::OnPane(wxCommandEvent &WXUNUSED(event))  // wxGlade: SQLServerNewDB.<event_handler>
{
    switch( m_panes->GetSelection() )
    {
    case 0:
        m_mainPanel1->Show();
        m_mainPanel2->Hide();
        m_mainPanel3->Hide();
        m_dbName->SetFocus();
        break;
    case 1:
        m_mainPanel1->Hide();
        m_mainPanel2->Show();
        m_mainPanel3->Hide();
        break;
    case 2:
        m_mainPanel1->Hide();
        m_mainPanel2->Hide();
        m_mainPanel3->Show();
        break;
    }
    Layout();
}


